rows, cols = 5, 7
sources = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 2]

def compute_output(grid, rows, cols):
    new_grid = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                continue  # keep sources

            # Check if any source is at Manhattan distance 1 (orthogonal neighbor)
            for sr, sc in sources:
                manhattan = abs(r - sr) + abs(c - sc)
